impl AsRef<AccountProject> for AccountProject { fn as_ref(&self) -> &Self { self } }
impl AsRef<Q> for AccountProject { fn as_ref(&self) -> &Q { &self.q } }

impl Default for AccountProject { fn default() -> Self { query() } }

fn collect(rows: &mut db::Rows, key_fn: Option<&(dyn Fn(&AccountProjectRow) -> Key + Send + Sync)>) -> Result<Collection<AccountProjectRow>> {
    use orm::Src as _;
    let cells = rows.take_cells();
    let mut c = Collection::with_capacity(cells.len());
    for mut src in cells {
        let key_values = rows.assemble.key.iter().map(|reference| src.val(reference.index)).collect::<Result<Vec<_>>>()?;
        let k = Key::of_values(&key_values);
        let r = AccountProjectRow::from_row(&mut src, &rows.assemble, rows)?;
        let k = match key_fn { Some(f) => f(&r), None => k };
        c.put(k, r);
    }
    Ok(c)
}
